/* Field-by-field notes checked against MSC Nastran 2020 SP1 QRG, PDF page numbers. */
(() => {
 const f=(meaning,blank,example,extra={})=>({meaning,blank,example,...extra});
 const eid=f('この要素そのものに付ける番号です。要素は、節点をつないで作る棒・板・立体の小さな部品です。番号は名前札の役目で、大きさや硬さを表しません。','省略できません。他の要素と重ならない正の整数を入れます。','100なら「要素100」。GRIDの節点番号100とは別の種類の番号です。',{link:'basics.html#ids'});
 const point=(name,role,optional=false)=>{const id=name==='GA'?12:name==='GB'?13:10+Number(name.replace(/\D/g,''));return f(`${name}は${role}のGRID番号です。ここには座標値ではなく、別のGRIDカードに付けた番号を書きます。`,optional?'この辺の途中の節点を使わない場合は空欄または0にできます。通常のSOL 101要素では一部だけ使う形もあります。':'この位置の節点は省略できません。定義済みの正のGRID番号を指定し、別の角・端と同じ番号にしません。',`${name}=${id}なら、GRIDのIDが${id}の点をこの位置につなぎます。`,{link:'basics.html#node'});};
 const g={};
 g.GRID={pages:[2151,2152],rows:[['GRID','ID','CP','X1','X2','X3','CD','PS','SEID','次行']],fields:{
  ID:f('節点の名前札です。節点とは、模型に置く「位置と動きを計算する点」です。たとえば物差しの両端に節点を置き、その間を棒要素でつなぎます。','省略できません。1〜99999999の整数を、ほかの節点と重ならないように付けます。','ID=2なら「節点2」。SPC1やFORCEで2を指定すると、この点が対象になります。',{link:'basics.html#node'}),
  CP:f('X1・X2・X3を読むための「ものさしの向き」を選ぶ番号です。節点をどの位置に置くかに関係します。','GRDSETによる共通指定があれば、そのCPを使います。なければ0＝基本座標系です。','CP=0、X1=1000.、X2=0.、X3=0.なら基本座標のX方向へ1000 mmの位置。',{link:'coordinates.html#systems',tip:'CPを変えてもCDが自動で同じ番号になるわけではありません。'}),
  X1:f('CPで選んだ座標系の第1の位置です。直交座標ならX、円筒座標ならZ軸からの距離R、球座標なら原点からの距離Rです。','0.0として扱われます。「分からない位置」という意味にはなりません。','この教材の直交座標・mmの例では1000.と書くとX=1000 mm。',{link:'coordinates.html#systems'}),
  X2:f('CPで選んだ座標系の第2の位置です。直交座標ならY、円筒・球座標なら角度θです。','0.0として扱われます。角度の欄なら0度です。','CP=0で25.ならY=25 mm。円筒座標なら25.は25度なので意味が違います。',{link:'coordinates.html#systems'}),
  X3:f('CPで選んだ座標系の第3の位置です。直交・円筒座標ならZ、球座標なら角度φです。','0.0として扱われます。','CP=0で0.ならZ=0の面に置きます。X3を空けてもCD欄を左に詰めません。',{link:'coordinates.html#systems'}),
  CD:f('その節点の「動く方向のものさし」です。変位、拘束の成分1〜6、節点の反力などを、どの軸で読むかを決めます。位置を置くCPとは役目が違います。','GRDSETによる共通指定があれば、そのCDを使います。なければ0＝基本座標系です。','CD=0ならSPC1の成分1は基本X方向。CD=10なら座標系10の第1方向です。',{link:'basics.html#dof',tip:'−1は流体と構造を連成する解析の流体節点用です。通常の構造の静解析では使いません。'}),
  PS:f('この節点で、常に動きを止める成分番号を書きます。1・2・3は各軸方向の移動、4・5・6は各軸まわりの回転です。「123」は百二十三ではなく、1と2と3の3つを選ぶ記号です。','GRDSETにPSの共通指定があれば引き継ぎます。なければ、この欄による拘束はありません。ただし別のSPC/SPC1や剛体結合で拘束される場合はあります。','PS=123なら3方向の移動を0にします。PS=123456なら6成分を0にします。方向はCDが基準です。',{link:'basics.html#constraints',tip:'PSには拘束セット番号を書きません。Case ControlのSPC選択とは独立して有効なので、解析ケースごとに拘束を替えるならSPC/SPC1が使いやすくなります。'}),
  SEID:f('大きな模型を複数の部分に分けて計算するとき、この節点が属するスーパーエレメントの番号です。「部分ごとに計算して、全体につなぎ直す」ための上級者向けの設定です。','GRDSETの共通指定があれば引き継ぎ、なければ0です。0は残余構造で、分割しない通常モデルもここに含まれます。','普通の棒1本の例では空欄で構いません。3を入れるのは、スーパーエレメント3として分割する設定を別途用意した場合です。',{tip:'部品を色分けするだけの番号ではありません。SESETによって指定が上書きされる場合もあります。'})
 }};
 g.CORD2R={pages:[1620,1621],rows:[['CORD2R','CID','RID','A1','A2','A3','B1','B2','B3','次行'],['継続行','C1','C2','C3','空欄','空欄','空欄','空欄','空欄','次行']],layoutNote:'点Cのための2行目は必須です。A・B・Cは、ここで座標を直接書く3つの点で、GRIDの番号ではありません。',fields:{
  CID:f('新しく作る座標系に付ける番号です。GRIDのCP/CDなどから、この番号を指定して使います。','省略できません。0は既にある基本座標なので、新しい座標系には0より大きい整数を付けます。','10と書くと「座標系10」を定義します。',{link:'basics.html#ids'}),
  RID:f('点A・B・Cの座標を読む基準の座標系です。新しく作るCIDとは別の番号です。','0＝基本座標系を使います。','RID=0なら、A・B・Cを基本XYZで記述します。RID=20なら、先に別途定義した座標系20で記述します。',{link:'coordinates.html#systems'})
 }};
 for(const [prefix,role,example] of [['A','新しい座標系の原点A',['0.','0.','0.']],['B','原点Aから見た+z方向を決める点B',['0.','0.','1.']],['C','A・Bと一緒にxz平面を決める点C',['1.','0.','0.']]])for(let i=1;i<=3;i++)g.CORD2R.fields[prefix+i]=f(`${role}の第${i}座標です。RIDが直交座標なら${['X','Y','Z'][i-1]}の位置を書きます。`,'QRGはこの欄の既定値を示していません。この教材では省略せず、0の位置も0.と明示します。',`${prefix}${i}=${example[i-1]}。${prefix}全体では(${example.join(' / ')})を入力する例です。`,{tip:prefix==='A'?'原点は3つの座標を合わせて決まります。':prefix==='B'?'BはAと違う位置にします。A→Bが+zの向きです。':'Cは直線ABの上に置きません。Cは+x側を決めますが、必ずしもx軸上の点ではありません。',link:'coordinates.html#systems'});
 g.CROD={pages:[1668],rows:[['CROD','EID','PID','G1','G2','空欄','空欄','空欄','空欄','次行']],fields:{EID:eid,
  PID:f('この棒が使う太さ・材料などの設定を選ぶ番号です。同じPIDを持つPRODカードを探しに行きます。','EIDと同じ番号を使います。その番号のPRODが実際に定義されている必要があります。','PID=200ならPRODのPID=200を参照します。200 mmという長さではありません。',{link:'basics.html#ids'}),G1:point('G1','棒の一方の端'),G2:point('G2','棒のもう一方の端')
 }};
 g.CBAR={pages:[1504,1505,1506,1507,1508],rows:[['CBAR','EID','PID','GA','GB','X1 / G0','X2','X3','OFFT','次行'],['継続行','PA','PB','W1A','W2A','W3A','W1B','W2B','W3B','次行']],layoutNote:'2行目は端の解放や位置のずらしがある場合に使います。第1行第6欄は、実数ならX1、整数ならG0という別の指定方法です。',fields:{EID:eid,
  PID:f('断面の太さ・曲げにくさなどを定めるプロパティ番号です。PBAR、PBARLなどを参照します。','BARORで共通のPIDが指定されていればそれを使い、なければEIDと同じ番号になります。参照先を別途定義する必要があります。','PID=400ならPBARのPID=400を使用する例です。',{link:'basics.html#ids'}),GA:point('GA','梁のA側の接続点'),GB:point('GB','梁のB側の接続点'),
  'X1 / G0':f('梁の断面をどちらへ向けるか決める欄です。実数のX1なら方向ベクトルの第1成分、整数のG0なら向きの目印にするGRID番号です。','BARORの向きの共通指定があれば使用します。なければこの教材では向きを省略せず指定します。3成分とも0のベクトルでは向きを決められません。','X1=0.、X2=1.、X3=0.なら第2方向を目印にします。G0=30ならGA→節点30を目印にし、X2/X3は空けます。',{tip:'1と1.は同じ意味になりません。G0はGA・GB以外の節点を選び、目印の方向を梁の軸と平行にしません。',link:'coordinates.html#elements'}),
  X2:f('ベクトル方式で断面の向きを決める、第2方向の成分です。力の大きさや節点の位置ではありません。','G0方式なら空欄にします。ベクトル方式でBARORの共通指定を使わない場合は、0の成分も0.と明示します。','X1=0.、X2=1.、X3=0.なら、選んだ座標系の第2方向を断面の向きの目印にします。',{link:'coordinates.html#elements'}),
  X3:f('ベクトル方式で断面の向きを決める、第3方向の成分です。X1・X2と合わせた矢印で向きを決めます。','G0方式なら空欄にします。ベクトル方式でBARORの共通指定を使わない場合は、0の成分も0.と明示します。','X1=0.、X2=0.、X3=1.なら第3方向が目印です。',{link:'coordinates.html#elements'}),
  OFFT:f('向きのベクトルと、両端をずらすベクトルを、どの座標系で読むかを3文字で指定します。1文字目が向き、2文字目がA端のずれ、3文字目がB端のずれです。','BARORに共通指定がなければGGGです。Gは該当節点のCDの軸、Bは基本軸、Oは節点間方向と目印から作るオフセット用の軸を指します。','BGGなら、向きは基本軸、A端のずれはGAのCD、B端のずれはGBのCDで読みます。',{tip:'1文字目はG/B、2・3文字目はG/Oから選びます。Oは数字の0ではありません。',link:'coordinates.html#elements'}),
  PA:f('梁のA端で、接続を外す動きの成分です。例えば回転のつながりを外すと、その方向の曲げモーメントを渡さないピンに近い接続を表せます。','端Aの接続を解放しません。地面へ固定するという意味ではなく、節点と梁端の接続を通常どおり保ちます。','PA=6なら、A端の要素z軸まわりの回転のつながりを外します。',{tip:'1〜6を最大5個まで指定します。方向は要素座標です。SPCの「動きを止める」とは逆の操作で、対象成分の剛性が梁に必要です。',link:'basics.html#constraints'}),
  PB:f('梁のB端で、接続を外す成分です。PAはA端、PBはB端という違いがあります。','端Bの接続を解放しません。','PB=6ならB端の要素z軸まわりの回転のつながりを外します。',{tip:'不要な解放を増やすと、構造が支えられず自由に動いてしまう場合があります。',link:'basics.html#constraints'})
 }};
 for(const end of ['A','B'])for(let i=1;i<=3;i++)g.CBAR.fields[`W${i}${end}`]=f(`節点G${end}から実際の梁端${end}まで、どれだけずらすかの第${i}成分です。中心線が節点の位置を通らない梁を表します。`,'0.0＝その方向にはずらしません。3成分とも0なら梁端と節点の位置は同じです。',`W${i}${end}=5.なら、OFFTで指定した軸の第${i}方向へ5 mmずらします。`,{unit:'長さ（この教材ではmm）',tip:'節点自体の位置は変わりません。ずれは剛体的な腕として扱われ、力とモーメントの伝わり方も変わります。',link:'coordinates.html#elements'});
 for(const [id,n,pages] of [['CQUAD4',4,[1644,1645,1646]],['CTRIA3',3,[1700,1701,1702]]]){
  const first=[id,'EID','PID',...Array.from({length:n},(_,i)=>'G'+(i+1)),'THETA / MCID','ZOFFS'];while(first.length<9)first.push('空欄');first.push('次行');
  const second=['継続行','空欄','TFLAG',...Array.from({length:n},(_,i)=>'T'+(i+1))];while(second.length<9)second.push('空欄');second.push('次行');
  g[id]={pages,rows:[first,second],layoutNote:'2行目は節点ごとの板厚を指定するときに使います。均質なPSHELLの基本例では、省略するとPSHELLのTが使われます。積層材のPCOMPなどではTiによる板厚変更は使いません。',fields:{EID:eid,
   PID:f('この板の厚さや材料をまとめたプロパティ番号です。均質な板ではPSHELLを参照します。','EIDと同じ番号を使います。その番号のPSHELLなどが別途必要です。','PID=600ならPSHELLのPID=600に書いた板厚と材料を使います。',{link:'basics.html#ids'}),
   'THETA / MCID':f('板の材料方向を決める欄です。実数なら角度THETA、整数なら座標系番号MCIDとして読みます。材料が方向によって強さの違う場合などに重要です。','THETA=0.0度です。材料の基準方向をG1→G2側に取ります。','30.なら角度30度。30なら座標系30の軸を板面へ投影して材料方向を決めます。',{tip:'同じ数字でも小数点の有無で意味が変わります。材料方向と、変位のCDや応力表示の軸は区別します。',link:'coordinates.html#elements'}),
   ZOFFS:f('節点で作った面から、板を計算する基準面までのずれです。正の値なら要素の+z方向へずらします。板厚そのものではありません。','ずれを指定しない基本形です。この教材では0.0＝節点面と基準面が一致する例を使います。','ZOFFS=1.なら+zへ1 mm。厚さ2 mmの指定はPSHELLのTなどに書きます。',{unit:'長さ（mm）',tip:'均質板でZOFFSを使う場合はPSHELLのMID1とMID2の両方が必要です。応力を読む表裏の基準にも注意します。',link:'coordinates.html#shell'}),
   TFLAG:f('次のT1〜T'+n+'を「厚さそのもの」として読むか、「PSHELLの厚さに掛ける倍率」として読むかの切替です。','0と同じ扱いで、Tiを厚さとして読みます。2行目全体を省略すればPSHELLのTを使います。','0ならT1=2.は2 mm。1ならT1=2.はPSHELLの厚さの2倍です。',{tip:'0か1の整数です。TFLAGを変えると、同じTiの数値でも厚さが変わります。'})
  }};
  for(let i=1;i<=n;i++){
   g[id].fields['G'+i]=point('G'+i,`板の周囲を順にたどった${i}番目の角`);
   g[id].fields['T'+i]=f(`角G${i}での板厚です。角ごとに変えることで、厚さが一定でない板を表せます。TFLAG=1のときは厚さの倍率です。`,'TFLAG=0/空欄ではPSHELLのTを使用します。TFLAG=1では倍率1.0を使用します。',`PSHELLのT=2.のとき、TFLAG=0でT${i}=3.なら3 mm。TFLAG=1でT${i}=1.5でも3 mmです。`,{tip:'指定する値は正の実数です。参照先PSHELLのTも空欄なら厚さを決められません。厚さはどちらかで必ず指定します。空欄と0.は同じではなく、0で板を消すための欄でもありません。'});
  }
 }
 const edgeMap={CTETRA:[[1,2],[2,3],[3,1],[1,4],[2,4],[3,4]],CHEXA:[[1,2],[2,3],[3,4],[4,1],[1,5],[2,6],[3,7],[4,8],[5,6],[6,7],[7,8],[8,5]]};
 for(const [id,n,total,pages] of [['CTETRA',4,10,[1697,1698]],['CHEXA',8,20,[1568,1569]]]){
  const names=Array.from({length:total},(_,i)=>'G'+(i+1));const rows=[[id,'EID','PID',...names.slice(0,6),'次行']];
  for(let i=6;i<total;i+=8){const row=['継続行',...names.slice(i,i+8)];while(row.length<9)row.push('空欄');row.push('次行');rows.push(row);}
  g[id]={pages,rows,layoutNote:`G1〜G${n}は角の必須節点。G${n+1}〜G${total}は辺の途中に追加できる節点です。${id==='CHEXA'?'8節点の形でもG7・G8を書くために2行目が必要で、3行目は追加節点を使うときだけです。':'4節点の形ならG5以降と2行目を省略できます。'}`,fields:{EID:eid,
   PID:f('立体要素が使う材料・計算方法などをまとめたプロパティ番号です。通常の線形静解析ではPSOLIDを参照します。','省略できません。CRODやシェルのように自動でEIDと同じ番号になる欄ではありません。','PID=801ならPSOLIDのPID=801を参照します。',{link:'basics.html#ids'})
  }};
  for(let i=1;i<=total;i++){
   const role=i<=n?`立体の${i}番目の角`:`辺G${edgeMap[id][i-n-1][0]}–G${edgeMap[id][i-n-1][1]}の途中`;
   g[id].fields['G'+i]=point('G'+i,role,i>n);
   g[id].fields['G'+i].tip=i<=n?(id==='CHEXA'?'G1〜G4を1つの面の周囲に並べ、反対側にG5〜G8を置きます。G1の向かいはG5、G2の向かいはG6です。':'G1・G2・G3で三角形の面、G4がその面から離れた頂点です。4点を同じ平面上に置きません。'):'空欄でもソフトが新しいGRID番号を勝手に作るわけではありません。この節点との接続を持たない形になります。ここでの省略規則は通常の線形要素用です。';
  }
 }
 window.FIELD_GUIDE=Object.assign(window.FIELD_GUIDE||{},g);
})();
